{
  "$id": "https://schema.merajutasa.id/events/public-event-v1.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "PublicEventV1",
  "type": "object",
  "required": [
    "schema_version",
    "event_name",
    "event_id",
    "occurred_at",
    "received_at",
    "session_id",
    "user_type",
    "page",
    "source",
    "integrity",
    "privacy"
